import{_ as t,o,c as d,a4 as s}from"./chunks/framework.BBs01uty.js";const p=JSON.parse('{"title":"机制八：交互原语（src/interaction.ts + src/ui/overlay*.ts）","description":"","frontmatter":{},"headers":[],"relativePath":"agent-cli/mechanisms/interaction.md","filePath":"agent-cli/mechanisms/interaction.md"}'),c={name:"agent-cli/mechanisms/interaction.md"};function a(r,e,i,n,l,h){return o(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="机制八-交互原语-src-interaction-ts-src-ui-overlay-ts" tabindex="-1">机制八：交互原语（<code>src/interaction.ts</code> + <code>src/ui/overlay*.ts</code>） <a class="header-anchor" href="#机制八-交互原语-src-interaction-ts-src-ui-overlay-ts" aria-label="Permalink to &quot;机制八：交互原语（`src/interaction.ts` + `src/ui/overlay*.ts`）&quot;">​</a></h1><blockquote><p>AC-27：<strong>UI 层（权限审批 / Hook 信任）与 LLM 层（<code>ask_user</code>）必须走同一实现分派路径</strong>。 这一层的存在就是为了守住它。</p></blockquote><h2 id="_1-为什么要有分派中枢" tabindex="-1">1. 为什么要有分派中枢 <a class="header-anchor" href="#_1-为什么要有分派中枢" aria-label="Permalink to &quot;1. 为什么要有分派中枢&quot;">​</a></h2><p>交互原语有多个消费者（见下）。如果每个各写一次 <code>openXxx(cb)</code> + 回调转 Promise 的胶水， 键位语义、Esc 语义、非交互降级就会各写一遍且必然漂移。所以收敛成一个入口：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">broker.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">request</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(spec): </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Promise</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InteractionResult</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><code>spec</code> 是<strong>要问什么</strong>（数据），<code>result</code> 是<strong>用户答了什么</strong>（数据）—— 中间怎么渲染、怎么按键， 全部由 TUI / questions 引擎统一处理。</p><h2 id="_2-当前消费者-broker-request-的全部调用点" tabindex="-1">2. 当前消费者（<code>broker.request</code> 的全部调用点） <a class="header-anchor" href="#_2-当前消费者-broker-request-的全部调用点" aria-label="Permalink to &quot;2. 当前消费者（`broker.request` 的全部调用点）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>消费者</th><th>调用点</th><th>spec 形态</th></tr></thead><tbody><tr><td>权限审批</td><td><code>index.ts</code> <code>createApprovalRequest</code></td><td>questions 4 选项（bash / edit 分档，V-1 默认高亮&quot;拒绝&quot;）</td></tr><tr><td><code>/mode</code> 模式选择</td><td><code>index.ts</code> <code>runModeCommand</code></td><td>select（固定 4 项，V-5 高度 6 行）</td></tr><tr><td>工作区权限信任</td><td><code>index.ts</code>（FR-8）</td><td>confirm（默认&quot;不信任&quot;，<code>forced</code>）</td></tr><tr><td>Hook 信任</td><td><code>hooks.ts</code> 经 <code>requestConfirm</code> 透传</td><td>confirm（列出全部命令）</td></tr><tr><td>LLM <code>ask_user</code></td><td>工具实现经 <code>ctx.interaction</code></td><td>select / input</td></tr></tbody></table><blockquote><p>历史注：设计时的消费者还包括 <code>/jobs</code>，FR-7 入口收敛时已删除。</p></blockquote><h2 id="_3-spec-形态与结果壳" tabindex="-1">3. spec 形态与结果壳 <a class="header-anchor" href="#_3-spec-形态与结果壳" aria-label="Permalink to &quot;3. spec 形态与结果壳&quot;">​</a></h2><p><code>InteractionSpec</code> 四种：<code>confirm</code>（是/否）· <code>select</code>（单选列表）· <code>input</code>（自由文本）· <code>questions</code>（1~4 问原生形态）。</p><ul><li>渲染<strong>只有一套实现</strong>：questions 引擎（<code>ui/overlay-questions.ts</code>）。 旧三形态由 <code>ui/overlay.ts</code> 的 <code>specToQuestions</code> <strong>折叠</strong>成 questions 规格 —— 调用方零改动。</li><li>结果回填：<code>mapAnswer</code> 把 questions 答案转回旧的 <code>OverlaySubmit</code> 兼容壳（<code>confirm</code> / <code>select</code> / <code>input</code>）， 所以消费者拿到的仍是自己熟悉的形状。已知偏差：审批语义以 <code>index</code> 表达（0 允许一次 / 1 永远允许或本会话 / 2 拒绝 / 3 拒绝并说明），而非 design 原文的 <code>value</code> 字段。</li></ul><h2 id="_4-降级分支-全部集中在这一个函数里-d9-v-1" tabindex="-1">4. 降级分支（全部集中在这一个函数里，D9 + V-1） <a class="header-anchor" href="#_4-降级分支-全部集中在这一个函数里-d9-v-1" aria-label="Permalink to &quot;4. 降级分支（全部集中在这一个函数里，D9 + V-1）&quot;">​</a></h2><p><code>InteractionResult = OverlayResult | { kind:&#39;unavailable&#39;, reason, message? }</code>。 <code>unavailable</code> 是<strong>快速失败</strong>的降级结果（语义 = &quot;本次交互没有被执行&quot;），两种原因：</p><table tabindex="0"><thead><tr><th>reason</th><th>触发</th><th>后果</th></tr></thead><tbody><tr><td><code>non-interactive</code></td><td>无 TUI 或 stdin 非 TTY（D9）</td><td>默认拒绝；单轮模式下写类 / bash 自动拒绝（退出码 2）</td></tr><tr><td><code>forced</code></td><td><code>--yes</code> 下遇到强制审批规则（危险命令，V-1）</td><td>必须显式 <code>bypass</code> 模式（且仍人工确认）</td></tr></tbody></table><p><code>--yes</code> 的自动接受<strong>只作用于非 forced 的普通询问</strong>；<code>forced</code>（危险命令 / 工作区信任）不被覆盖 —— 安全优先。</p><h2 id="_5-直渲-vs-broker-两条分发路-v-2" tabindex="-1">5. 直渲 vs broker 两条分发路（V-2） <a class="header-anchor" href="#_5-直渲-vs-broker-两条分发路-v-2" aria-label="Permalink to &quot;5. 直渲 vs broker 两条分发路（V-2）&quot;">​</a></h2><p>AC-27 要求<strong>渲染入口唯一</strong>（<code>ui.openInteractionOverlay</code>），但分发有两类：</p><ul><li><strong>broker 路径</strong>：需要&quot;等一个结果&quot;的（审批 / 信任 / <code>ask_user</code> / <code>/mode</code>）—— <code>request(spec)</code> → <code>createSpecSession</code> → 挂起 → 结果回填。</li><li><strong>直渲路径</strong>：纯 UI 选择、不需要回传给 LLM 的（<code>/model</code> 两页弹层、任务面板）—— 直接 <code>createQuestionsSession</code> / <code>createPanelSession</code> 挂到同一入口。</li></ul><p>两条路都过唯一渲染入口（代码检索锁在 <code>interaction.test.ts</code>），但只有 broker 路径参与 AC-27 的&quot;UI 层与 LLM 层同路径&quot;。</p><h2 id="_6-分层纪律" tabindex="-1">6. 分层纪律 <a class="header-anchor" href="#_6-分层纪律" aria-label="Permalink to &quot;6. 分层纪律&quot;">​</a></h2><p><code>interaction.ts</code> <strong>不碰 stdin/stdout</strong>（唯一例外：ui 缺失时的 stderr 提示）；UI 通过结构化 <code>InteractionHost</code> 注入 —— 单测注入记录型假 host 即可，不必起 TUI。</p><h2 id="_7-测试" tabindex="-1">7. 测试 <a class="header-anchor" href="#_7-测试" aria-label="Permalink to &quot;7. 测试&quot;">​</a></h2><p><code>interaction.test.ts</code>：唯一入口的代码检索锁、broker 降级分支、spec→questions 折叠往返、结果壳映射。</p>',24)])])}const k=t(c,[["render",a]]);export{p as __pageData,k as default};
